('advanced-native-2106', '["phrase"]'::jsonb, '{"advanced-native-2106-v1-audio":{"type":"mc","answers":["One person is doing the listed work, while the suggested sharing is not yet agreed."],"options":["The organiser has stopped all festival work while waiting.","The message says she is responsible for messages only.","One person is doing the listed work, while the suggested sharing is not yet agreed.","The volunteers have already taken over the booking and preparation."]},"advanced-native-2106-v2-reply":{"type":"mc","answers":["The listed booking, messages and preparation have not yet been shared with confirmed volunteers.","The proposed roles have not yet reduced the work she is doing.","There is a practical gap between suggesting help and having people agree to it.","She should not carry the whole load while several festival duties are still on her alone."],"options":["The listed booking, messages and preparation have not yet been shared with confirmed volunteers.","The proposed roles have not yet reduced the work she is doing.","There is a practical gap between suggesting help and having people agree to it.","She should not carry the whole load while several festival duties are still on her alone."]},"advanced-native-2106-v1-scene":{"type":"mc","answers":["A final signature alone does not show that he carried the whole load; the account documents work shared among three people."],"options":["The record says the proposed roles are still unaccepted.","A final signature alone does not show that he carried the whole load; the account documents work shared among three people.","The signature establishes that the other two people did no preparation."]},"advanced-native-2106-v1-contrast":{"type":"mc","answers":["An effective division of work has already been agreed and completed."],"options":["The speaker thinks all the relevant work should not rest on her alone.","An effective division of work has already been agreed and completed.","More context can identify the work